{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "GSK2838232, a complex pentacyclic triterpenoid-like molecule bearing a carboxylic acid and polar substituents, showed poor oral bioavailability in initial human clinical studies; its shared large fused-ring acid scaffold supports low F for the query despite modest Morgan similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Glycyrrhizin, a triterpenoid with multiple carboxylic acids, has poor/low oral bioavailability in humans with unchanged drug bioavailability around 0.25%, directly supporting low oral bioavailability for the query's triterpenoid acid framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Oleanolic acid, a pentacyclic triterpenoid carboxylic acid, showed poor oral bioavailability in healthy volunteers with very low AUC and Cmax, providing relevant experimental evidence that this scaffold class is poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Soticlestat, a smaller heteroaryl amide, had an absolute oral bioavailability of 12.6% in healthy volunteers, below the 20% threshold; although structurally distant, it reinforces that molecules with high polarity and large size tend to have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Rilzabrutinib, a small molecule, had absolute oral bioavailability of only about 4.7–6.4% in humans, supporting low F; its low transferability is outweighed by the consistent low-bioavailability pattern among the more relevant analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DJ-927, a taxane, showed high oral bioavailability in patients, but its different scaffold and low Morgan similarity make it weak contradictory evidence that does not overcome the strong low-bioavailability pattern from triterpenoid acid analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low. The query is a large zwitterionic pentacyclic triterpenoid acid (MW ~730, logP ~8.6, TPSA ~125) with multiple physicochemical barriers to absorption. The most transferable experimental analogues—triterpenoid acids such as glycyrrhizin and oleanolic acid, plus the complex pentacyclic acid GSK2838232—show poor or low oral bioavailability in humans. Structurally distant small molecules with high oral bioavailability do not override this consistent pattern.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query or a close analogue.",
    "No data on solubility-enabling formulations or prodrug strategies that might improve absorption.",
    "No transporter or metabolism data to assess whether efflux or first-pass clearance dominates.",
    "All Morgan similarities are low (<0.22), limiting direct structural transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

